// Auto-generated by scripts/build-worker.mjs — do not edit by hand.
export const guides = [{"name":"RichTextBold","fa":"متن ضخیم","code":"<b>Bold text</b>","description":"Emphasize important text. Nest with italic or underline.","descriptionFa":"برای تأکید بر متن؛ قابل ترکیب با ایتالیک و زیرخط.","group":"Rich text"},{"name":"RichTextItalic","fa":"ایتالیک","code":"<i>Italic text</i>","description":"Use italic text for emphasis, titles, or a different voice.","descriptionFa":"متن مورب برای تأکید یا عنوان.","group":"Rich text"},{"name":"RichTextUnderline","fa":"زیرخط","code":"<u>underlined text</u>, <ins>underlined text</ins>","description":"Both u and ins underline their content.","descriptionFa":"هر دو تگ u و ins زیر متن خط می‌کشند.","group":"Rich text"},{"name":"RichTextStrikethrough","fa":"خط‌خورده","code":"<s>Old idea</s> New idea","description":"Mark removed or replaced text. Markdown: ~~text~~.","descriptionFa":"برای متن حذف‌شده؛ در مارک‌داون از ~~text~~ استفاده کنید.","group":"Rich text"},{"name":"RichTextSpoiler","fa":"اسپویلر","code":"<tg-spoiler>A little secret</tg-spoiler>","description":"Content is concealed until the reader clicks it. Markdown: ||text||.","descriptionFa":"محتوا تا زمان کلیک پنهان می‌ماند.","group":"Rich text"},{"name":"RichTextDateTime","fa":"تاریخ و زمان","code":"<tg-time unix=\"1647531900\" format=\"wDT\">22:45 tomorrow</tg-time>","description":"Use a Unix timestamp in seconds. Telegram localizes the date and time; the preview uses your browser locale.","descriptionFa":"زمان یونیکس برحسب ثانیه است؛ تلگرام زمان را با منطقه زمانی کاربر نمایش می‌دهد.","group":"Rich text"},{"name":"RichTextTextMention","fa":"منشن کاربر","code":"<a href=\"tg://user?id=777000\">Telegram</a>","description":"Mention a user by numeric ID, subject to their privacy settings.","descriptionFa":"منشن با شناسه عددی، وابسته به تنظیمات حریم خصوصی کاربر.","group":"Rich text"},{"name":"RichTextSubscript","fa":"زیرنویس","code":"H<sub>2</sub>O","description":"Render text below the baseline, for chemical formulas and indices.","descriptionFa":"نمایش زیر خط پایه برای فرمول شیمیایی و اندیس.","group":"Rich text"},{"name":"RichTextSuperscript","fa":"بالانویس","code":"x<sup>2</sup> + y<sup>2</sup>","description":"Render powers or ordinal markers above the baseline.","descriptionFa":"نمایش توان و شماره بالای خط پایه.","group":"Rich text"},{"name":"RichTextMarked","fa":"هایلایت","code":"<mark>Something worth highlighting.</mark>","description":"Highlight text. Markdown equivalent: ==text==.","descriptionFa":"برجسته کردن با پس‌زمینه؛ در مارک‌داون ==text==.","group":"Rich text"},{"name":"RichTextCode","fa":"کد","code":"<code>console.log(\"Hello\")</code>","description":"Inline monospaced code. Use pre for a multiline code block.","descriptionFa":"کد تک‌خطی با فونت ثابت؛ برای چند خط از pre استفاده کنید.","group":"Rich text"},{"name":"RichTextCustomEmoji","fa":"ایموجی سفارشی","code":"<tg-emoji emoji-id=\"5368324170671202286\">👍</tg-emoji>","description":"Supply a valid custom emoji identifier. The web preview shows its fallback emoji; Telegram resolves the asset.","descriptionFa":"شناسه معتبر ایموجی را وارد کنید. وب ایموجی جایگزین و تلگرام فایل اصلی را نشان می‌دهد.","group":"Rich text"},{"name":"RichTextMathematicalExpression","fa":"فرمول ریاضی","code":"<tg-math>\\frac{a^2 + b^2}{c}</tg-math>","description":"Inline LaTeX, rendered with KaTeX in the preview. Use $...$ in Markdown.","descriptionFa":"فرمول درون‌خطی LaTeX؛ رندر وب با KaTeX انجام می‌شود.","group":"Rich text"},{"name":"RichTextUrl","fa":"پیوند","code":"<a href=\"https://telegram.org\">Visit Telegram ↗</a>","description":"Link text to an HTTPS or supported tg:// destination.","descriptionFa":"پیوند به آدرس HTTPS یا آدرس پشتیبانی‌شده tg://.","group":"Rich text"},{"name":"RichTextEmailAddress","fa":"ایمیل","code":"<a href=\"mailto:hello@example.com\">hello@example.com</a>","description":"Email addresses are detected automatically unless skip_entity_detection is enabled.","descriptionFa":"ایمیل‌ها به صورت خودکار شناسایی می‌شوند مگر تشخیص خودکار غیرفعال باشد.","group":"Rich text"},{"name":"RichTextPhoneNumber","fa":"شماره تلفن","code":"<a href=\"tel:+12025550123\">+1 202 555 0123</a>","description":"A phone number link opens the device dialer.","descriptionFa":"پیوند شماره تلفن، شماره‌گیر دستگاه را باز می‌کند.","group":"Rich text"},{"name":"RichTextBankCardNumber","fa":"شماره کارت","code":"4111 1111 1111 1111","description":"Telegram can recognize bank card numbers. Use test values only in demos.","descriptionFa":"تلگرام شماره کارت را تشخیص می‌دهد. در نمونه فقط از شماره آزمایشی استفاده کنید.","group":"Rich text"},{"name":"RichTextMention","fa":"نام کاربری","code":"@telegram","description":"Telegram detects @username mentions and opens the corresponding profile.","descriptionFa":"تلگرام نام کاربری را شناسایی و پروفایل را باز می‌کند.","group":"Rich text"},{"name":"RichTextHashtag","fa":"هشتگ","code":"#TeleRich","description":"Use a hashtag to group and discover related messages.","descriptionFa":"هشتگ برای دسته‌بندی و جست‌وجوی پیام‌ها.","group":"Rich text"},{"name":"RichTextCashtag","fa":"نماد سهام","code":"$TELE","description":"A dollar-prefixed symbol is detected as a cashtag.","descriptionFa":"نماد با پیشوند دلار به عنوان کش‌تگ شناسایی می‌شود.","group":"Rich text"},{"name":"RichTextBotCommand","fa":"دستور ربات","code":"/start","description":"Commands start with /. Your bot handles them through message updates.","descriptionFa":"دستور با / شروع می‌شود و از طریق آپدیت پیام به ربات می‌رسد.","group":"Rich text"},{"name":"RichTextButton","fa":"دکمه ریچ","code":"<p>Inline buttons: <tg-button type=\"url\" style=\"success\" url=\"https://t.me\">url</tg-button> <tg-button type=\"url\" url=\"tg://user?id=777000\">user</tg-button> <tg-button type=\"callback_data\" style=\"link\" data=\"callback\">callback with the date <tg-time unix=\"1647531900\" format=\"wDT\">22:45 tomorrow</tg-time> and the custom emoji <tg-emoji emoji-id=\"5368324170671202286\">👍</tg-emoji></tg-button> <tg-button type=\"web_app\" style=\"danger\" url=\"https://telegram.org\">Mini App (private chats only)</tg-button> <tg-button type=\"switch_inline_query\" style=\"primary\" query=\"inline\">inline</tg-button> <tg-button type=\"switch_inline_query_current_chat\" query=\"inline 2\">inline 2</tg-button> <tg-button type=\"switch_inline_query_chosen_chat\" query=\"inline 3\" allow-user-chats allow-bot-chats allow-group-chats allow-channel-chats>inline 3</tg-button> <tg-button type=\"copy_text\" text=\"...copy\">Copy</tg-button> <tg-button type=\"disabled\">Disabled</tg-button></p>","description":"10.3: rich buttons come in two placements. Placed inline like this, a button flows inside a paragraph alongside regular text and other entities. Every action type works inline — url, callback_data, web_app, the three switch_inline_query variants, copy_text and disabled. Styles: primary, success, danger; link is callback-only. Colors follow the Telegram theme, not arbitrary hex values. For the normal, row-grouped placement, see Buttons below.","descriptionFa":"نسخه ۱۰.۳: دکمه‌های ریچ دو حالت چیدمان دارند. در این حالت درون‌خطی، دکمه داخل پاراگراف و کنار متن و سایر عناصر قرار می‌گیرد. همه نوع عمل به‌صورت درون‌خطی کار می‌کند: url، callback_data، web_app، سه حالت switch_inline_query، copy_text و disabled. رنگ‌ها primary، success و danger هستند؛ link فقط برای callback است. رنگ دلخواه هگز پشتیبانی نمی‌شود. برای حالت عادی و ردیفی به بخش «دکمه‌ها» مراجعه کنید.","group":"Rich text"},{"name":"RichTextAnchor","fa":"لنگر","code":"<a name=\"chapter-1\"></a><h3>Chapter 1</h3>","description":"Create a named target inside the message. Use an anchor link to jump here.","descriptionFa":"یک مقصد نام‌گذاری‌شده در پیام ایجاد کنید.","group":"Rich text"},{"name":"RichTextAnchorLink","fa":"پیوند لنگر","code":"<a href=\"#chapter-1\">Jump to chapter 1</a>","description":"Link to an anchor in the same rich message. The target name must match.","descriptionFa":"پیوند به لنگر داخل همان پیام؛ نام مقصد باید یکسان باشد.","group":"Rich text"},{"name":"RichTextReference","fa":"پاورقی","code":"A useful fact[^note].\n\n[^note]: The supporting explanation.","description":"Define a footnote in Rich Markdown with [^id]: and reference it using [^id].","descriptionFa":"تعریف پاورقی در مارک‌داون با [^id]: و ارجاع با [^id].","group":"Rich text"},{"name":"RichTextReferenceLink","fa":"ارجاع پاورقی","code":"Read the source[^source].\n\n[^source]: https://core.telegram.org/bots/api","description":"A reference link connects text to a footnote definition. IDs must be unique.","descriptionFa":"متن را به تعریف پاورقی متصل می‌کند؛ شناسه باید یکتا باشد.","group":"Rich text"},{"name":"RichBlockSectionHeading","fa":"عنوان‌ها","code":"<h1>Heading 1</h1>\n<h2>Heading 2</h2>\n<h3>Heading 3</h3>\n<h4>Heading 4</h4>\n<h5>Heading 5</h5>\n<h6>Heading 6</h6>","description":"Six heading levels. Markdown uses one to six # characters.","descriptionFa":"شش سطح عنوان؛ در مارک‌داون از یک تا شش # استفاده کنید.","group":"Blocks"},{"name":"RichBlockParagraph","fa":"پاراگراف","code":"<p>A paragraph with <b>rich text</b>.</p>","description":"Separate blocks of text with paragraphs or blank lines in Markdown.","descriptionFa":"متن‌ها را با پاراگراف یا خط خالی جدا کنید.","group":"Blocks"},{"name":"RichBlockList","fa":"فهرست","code":"- milk\n- eggs\n- [ ] todo\n- [x] done\n\n1. wake up\n2. ship it","description":"Unordered, ordered and task lists. List items support nested rich text.","descriptionFa":"فهرست مرتب، نامرتب و کارها؛ قابل استفاده با متن قالب‌بندی‌شده.","group":"Blocks"},{"name":"RichBlockBlockQuotation","fa":"نقل‌قول تو در تو","code":"<blockquote>A quote<blockquote>A nested thought</blockquote></blockquote>","description":"Nest blockquote tags to create multiple levels of quotation.","descriptionFa":"با قرار دادن تگ‌های blockquote داخل هم، نقل‌قول چندسطحی بسازید.","group":"Blocks"},{"name":"RichBlockPullQuotation","fa":"نقل‌قول برجسته","code":"<aside>Pull quote<cite>The Author</cite></aside>","description":"Pull quotes emphasize a passage. cite identifies its author.","descriptionFa":"نقل‌قول برجسته؛ cite برای نام نویسنده است.","group":"Blocks"},{"name":"RichBlockExpandableBlockQuotation","fa":"نقل‌قول بازشونده","code":"<blockquote expandable>Click to expand this quotation.\nMore content inside.</blockquote>","description":"10.3: a quotation that can expand or collapse. The browser preview uses an interactive disclosure.","descriptionFa":"نسخه ۱۰.۳: نقل‌قول قابل باز و بسته شدن.","group":"Blocks"},{"name":"RichBlockDetails","fa":"بخش بازشونده","code":"<details><summary>Closed by default</summary>Hidden content</details>\n<details open><summary>Open by default</summary>Visible content</details>","description":"summary provides the label. Add open to show content initially.","descriptionFa":"summary عنوان بخش است؛ open محتوا را از ابتدا نشان می‌دهد.","group":"Blocks"},{"name":"RichBlockTable","fa":"جدول","code":"<table bordered striped compact><caption>Table caption</caption>\n<tr><th>Feature</th><th>Status</th></tr>\n<tr><td align=\"left\">Rich buttons</td><td align=\"center\">Available</td></tr>\n<tr><td colspan=\"2\">Merged columns</td></tr>\n<tr><td rowspan=\"2\" valign=\"top\">Two rows</td><td>First</td></tr>\n<tr><td>Second</td></tr></table>","description":"bordered adds borders; striped alternates rows; compact reduces padding (is_compact in block JSON). colspan/rowspan merge cells. align: left/center/right; valign: top/middle/bottom. Keep a consistent grid when merging.","descriptionFa":"bordered برای حاشیه، striped برای سطرهای راه‌راه و compact برای فاصله کمتر. colspan و rowspan ادغام سلول‌ها هستند. align تراز افقی و valign تراز عمودی است؛ ساختار شبکه را حفظ کنید.","group":"Blocks"},{"name":"RichBlockMathematicalExpression","fa":"بلوک فرمول","code":"<tg-math-block>E = mc^2</tg-math-block>","description":"Display a LaTeX formula in its own block. Markdown: $$...$$.","descriptionFa":"فرمول LaTeX در یک بلوک مستقل؛ در مارک‌داون $$...$$.","group":"Blocks"},{"name":"RichBlockPreformatted","fa":"بلوک کد","code":"<pre><code class=\"language-javascript\">const hello = \"TeleRich\";\nconsole.log(hello);</code></pre>","description":"Preserve whitespace in multiline code. Set language-* for the language label.","descriptionFa":"حفظ فاصله‌ها در کد چندخطی؛ زبان را با language-* مشخص کنید.","group":"Blocks"},{"name":"RichBlockDivider","fa":"جداکننده","code":"<hr>","description":"Separate sections visually. Markdown equivalent: ---.","descriptionFa":"جداکننده بخش‌ها؛ معادل مارک‌داون ---.","group":"Blocks"},{"name":"RichBlockFooter","fa":"پانویس","code":"<footer>Made with TeleRich · 2026</footer>","description":"A muted footer for attribution and supplementary text.","descriptionFa":"پانویس برای اطلاعات تکمیلی و نام نویسنده.","group":"Blocks"},{"name":"RichBlockMap","fa":"نقشه","code":"<tg-map lat=\"41.9\" long=\"12.5\" zoom=\"14\"/>","description":"Set latitude, longitude and zoom. The web preview embeds OpenStreetMap; Telegram uses its native map renderer.","descriptionFa":"عرض جغرافیایی، طول و بزرگ‌نمایی را تنظیم کنید؛ وب از OpenStreetMap و تلگرام از نقشه بومی استفاده می‌کند.","group":"Media"},{"name":"RichBlockPhoto","fa":"عکس","code":"<img src=\"https://telegram.org/example/photo.jpg\"/>","description":"Use a public image URL or media mapped via tg://photo?id=. Example URLs are placeholders; supply your own asset.","descriptionFa":"آدرس عمومی عکس یا مدیای نگاشت‌شده tg://photo?id=؛ لینک نمونه را با فایل واقعی جایگزین کنید.","group":"Media"},{"name":"RichBlockVideo","fa":"ویدیو","code":"<video src=\"https://telegram.org/example/video.mp4\"/>","description":"Embed a publicly accessible video. The browser includes playback controls.","descriptionFa":"ویدیو با لینک عمومی؛ در وب کنترل پخش دارد.","group":"Media"},{"name":"RichBlockAudio","fa":"صوت","code":"<audio src=\"https://telegram.org/example/audio.mp3\"/>","description":"Embed audio with an HTTPS URL or a mapped Telegram media ID.","descriptionFa":"صوت با لینک HTTPS یا شناسه مدیای نگاشت‌شده.","group":"Media"},{"name":"RichBlockVoiceNote","fa":"پیام صوتی","code":"![](https://telegram.org/example/audio.ogg)","description":"An OGG voice note. InputMediaVoiceNote was added in 10.2.","descriptionFa":"پیام صوتی OGG؛ کلاس InputMediaVoiceNote از نسخه ۱۰.۲.","group":"Media"},{"name":"RichBlockAnimation","fa":"انیمیشن","code":"<img src=\"https://telegram.org/example/animation.gif\"/>","description":"Use a GIF or a supported animation asset.","descriptionFa":"از GIF یا فایل انیمیشن پشتیبانی‌شده استفاده کنید.","group":"Media"},{"name":"RichBlockCollage","fa":"کلاژ","code":"<tg-collage><img src=\"https://telegram.org/example/photo.jpg\"/><img src=\"https://telegram.org/example/photo.jpg\"/><figcaption>Caption<cite>The Author</cite></figcaption></tg-collage>","description":"Group images into a collage. figcaption and cite add a caption and attribution. Replace example URLs with real media.","descriptionFa":"چند عکس در کلاژ؛ figcaption برای توضیح و cite برای نویسنده. لینک‌ها را با فایل واقعی عوض کنید.","group":"Media"},{"name":"RichBlockSlideshow","fa":"اسلایدشو","code":"<tg-slideshow><img src=\"https://telegram.org/example/photo.jpg\"/><video src=\"https://telegram.org/example/video.mp4\"/><figcaption>Slideshow caption<cite>The Author</cite></figcaption></tg-slideshow>","description":"Combine photos and videos. Navigate between slides in the live preview.","descriptionFa":"ترکیب عکس و ویدیو؛ جابه‌جایی بین اسلایدها در پیش‌نمایش.","group":"Media"},{"name":"RichBlockDocument","fa":"سند","code":"<a href=\"tg://document?id=report\">Download report</a>","description":"10.3: documents can be embedded. Map the id to an InputRichMessageMedia document in rich_message.media; the link alone does not upload a file.","descriptionFa":"نسخه ۱۰.۳: سند؛ شناسه باید به document در rich_message.media نگاشت شود. پیوند به تنهایی فایل را آپلود نمی‌کند.","group":"Media"},{"name":"RichBlockButtons","fa":"دکمه‌ها","code":"<tg-button-row align=\"left\">\n  <tg-button type=\"url\" url=\"https://t.me\">url</tg-button>\n  <tg-button type=\"url\" style=\"success\" url=\"tg://user?id=777000\">user</tg-button>\n  <tg-button type=\"callback_data\" style=\"link\" data=\"callback\">callback</tg-button>\n</tg-button-row>\n<tg-button-row align=\"center\">\n  <tg-button type=\"web_app\" url=\"https://telegram.org\">Mini App (private chats only)</tg-button>\n</tg-button-row>\n<tg-button-row align=\"right\">\n  <tg-button type=\"switch_inline_query\" query=\"inline\">inline</tg-button>\n  <tg-button type=\"switch_inline_query_current_chat\" query=\"inline 2\">inline 2</tg-button>\n  <tg-button type=\"switch_inline_query_chosen_chat\" query=\"inline 3\" allow-user-chats allow-group-chats allow-channel-chats>inline 3</tg-button>\n</tg-button-row>\n<tg-button-row>\n  <tg-button type=\"copy_text\" text=\"...copy\">Copy</tg-button>\n  <tg-button type=\"disabled\" style=\"primary\">Disabled</tg-button>\n</tg-button-row>","description":"10.3: this is the normal placement — group buttons into rows with tg-button-row, each row aligned left, center or right (default: left). Combine any action types per row: url, callback_data, web_app, the three switch_inline_query variants, copy_text and disabled. Use the button builder to select action, style and row. For buttons flowing inside text instead, see the inline Button guide above.","descriptionFa":"نسخه ۱۰.۳: این حالت عادی است — دکمه‌ها را با tg-button-row در ردیف‌هایی گروه کنید که هرکدام می‌توانند تراز چپ، وسط یا راست داشته باشند (پیش‌فرض: چپ). هر نوع عمل در هر ردیف قابل ترکیب است: url، callback_data، web_app، سه حالت switch_inline_query، copy_text و disabled. نوع، رنگ و شماره ردیف را در سازنده انتخاب کنید. برای دکمه‌های درون‌خطی به راهنمای «دکمه ریچ» بالا مراجعه کنید.","group":"Blocks"},{"name":"RichBlockInlineKeyboard","fa":"کیبورد اینلاین","code":"<pre><code>{\n  \"reply_markup\": {\n    \"inline_keyboard\": [\n      [{ \"text\": \"Open\", \"url\": \"https://t.me\", \"style\": \"primary\" }],\n      [{ \"text\": \"Confirm\", \"callback_data\": \"yes\", \"style\": \"success\" }, { \"text\": \"Cancel\", \"callback_data\": \"no\", \"style\": \"danger\" }]\n    ]\n  }\n}</code></pre>","description":"A real Telegram inline keyboard attaches below the message as reply_markup, separate from rich buttons inside the text. Since Bot API 9.4 each button also accepts an optional style of primary, success or danger; omit it for the client’s default look. Use the inline button builder to create one visually.","descriptionFa":"کیبورد اینلاین واقعی تلگرام با reply_markup زیر پیام می‌چسبد؛ جدا از دکمه‌های ریچ داخل متن است. از نسخه ۹.۴ هر دکمه می‌تواند رنگ اختیاری primary، success یا danger داشته باشد؛ برای نمایش پیش‌فرض کلاینت آن را خالی بگذارید. برای ساخت بصری از سازنده دکمه اینلاین استفاده کنید.","group":"Blocks"}];
export const releases = [{"version":"10.3","date":"August 24, 2026","anchor":"august-24-2026","items":[["Rich messages","RichMessageButton, RichTextButton, RichBlockButtons and InputRichBlockButtons. Compact tables (is_compact). Expandable block quotations. RichBlockDocument, InputRichBlockDocument and tg://document?id= links.","دکمه‌های ریچ و گروه دکمه، جدول فشرده، نقل‌قول بازشونده و اسناد با tg://document?id=."],["Ephemeral messages","EphemeralMessageParameters replaces receiver_user_id and callback_query_id on send methods; sendRichMessage now accepts it. replace_callback_query_message replaces the original message. New file uploads in editEphemeralMessageMedia, show_caption_above_media in editEphemeralMessageCaption and rich_message in editEphemeralMessageText.","پارامتر یکپارچه پیام موقت؛ جایگزینی پیام اصلی، آپلود فایل در ویرایش مدیا و ویرایش متن ریچ و محل کپشن."],["Reply markup & permissions","DisabledButton and InlineKeyboardButton.disabled. force_reply in InlineKeyboardMarkup and ReplyKeyboardMarkup. can_send_welcome_messages in administrator rights, ChatMemberAdministrator and promoteChatMember.","دکمه غیرفعال، force_reply در کیبوردها و مجوز ارسال پیام خوش‌آمدگویی مدیر."],["Drafts & updates","can_stop and keep_on_stop in sendMessageDraft / sendRichMessageDraft. MessageGenerationStopped and Update.stopped_message_generation. CommunityChatJoined and Message.community_chat_joined. UniqueGiftInfo.text, entities and is_private.","توقف تولید پیش‌نویس و حفظ متن، آپدیت توقف تولید، پیوستن جامعه و فیلدهای جدید هدیه."]]},{"version":"10.2","date":"July 14, 2026","anchor":"july-14-2026","items":[["Structured input & media","InputRichMessage now accepts blocks or explicit media mappings via InputRichMessageMedia. InputRichBlock classes cover paragraphs, headings, lists, quotations, tables, details, maps, media and thinking. InputMediaVoiceNote is available.","ورودی بلوکی پیام ریچ، نگاشت مدیا و کلاس‌های بلوکی برای قالب‌بندی متن و پیام صوتی."],["Ephemeral messages","Private-to-user group messages: is_ephemeral, receiver_user and ephemeral_message_id. Edit text, media, caption and reply markup; delete with deleteEphemeralMessage. ReplyParameters can use ephemeral_message_id instead of message_id.","پیام گروهی خصوصی برای یک کاربر؛ ویرایش متن، مدیا، کپشن و کیبورد، حذف و پاسخ با شناسه پیام موقت."],["Communities & security","Community, CommunityChatAdded/Removed and ChatFullInfo.community. BotSubscriptionUpdated in Update.subscription. Mini Apps restrict API calls from other origins starting July 20, 2026. Keep navigation on your original Mini App domain.","جوامع، رویدادهای افزودن و حذف چت و اشتراک؛ امنیت مبدأ مینی‌اپ از ۲۰ ژوئیه ۲۰۲۶."]]},{"version":"10.1","date":"June 11, 2026","anchor":"june-11-2026","items":[["Rich messages introduced","RichText, RichBlock, RichMessage, InputRichMessage and InputRichMessageContent. sendRichMessage, sendRichMessageDraft and rich_message in editMessageText. Rich text supports all 26 original entity types and structured media blocks.","معرفی پیام ریچ، متن و بلوک، ارسال و استریم و ویرایش؛ ۲۶ نوع متن و بلوک‌های مدیا."],["Join requests & polls","supports_join_request_queries, guard_bot, ChatJoinRequest.query_id. answerChatJoinRequestQuery and sendChatJoinRequestWebApp. PollMedia.link, Link and InputMediaLink in poll options.","کوئری درخواست عضویت، بات نگهبان و پاسخ درخواست؛ پشتیبانی پیوند در مدیای نظرسنجی."]]}];
export const setup = [["Create your Telegram bot","ساخت ربات تلگرام","Open @BotFather, run /newbot and copy the bot token. Never paste this token into the web editor.","در @BotFather دستور /newbot را بفرستید و توکن را بردارید. توکن را هرگز داخل ویرایشگر وب وارد نکنید."],["Deploy your source repository","استقرار مخزن سورس","Deploy the TeleRich-Standalone repository with Cloudflare Git integration or Wrangler. BOT_STATE and its SQLite migration are required; the Worker imports index.js and library.js.","مخزن TeleRich-Standalone را با اتصال گیتهاب کلادفلیر یا Wrangler مستقر کنید. BOT_STATE و migration لازم‌اند؛ Worker از index.js و library.js استفاده می‌کند."],["Configure secrets & access","تنظیم رازها و دسترسی","In Worker Settings → Variables and Secrets, add BOT_TOKEN, WEBHOOK_SECRET (a random secret), and ADMIN_KEY (a different strong secret for browser administration). Optional ADMINS_ID is a comma-separated list of Telegram user IDs. Unset means all authenticated Telegram users can use the bot; set means only listed users.","در تنظیمات Worker، رازهای BOT_TOKEN و WEBHOOK_SECRET و ADMIN_KEY را با مقدارهای متفاوت و قوی اضافه کنید. ADMINS_ID اختیاری و فهرست شناسه عددی با کاما است؛ خالی یعنی استفاده عمومی کاربران احراز هویت‌شده."],["Enable your private gallery","فعال کردن گالری خصوصی","Activate R2, create a private telerich-library bucket and enable the MEDIA_LIBRARY r2_buckets binding in wrangler.jsonc. Redeploy. Photos and saved links are available under Photos & links; 20 of each. No public bucket or r2.dev URL is needed.","R2 را فعال کنید، باکت خصوصی telerich-library بسازید و binding با نام MEDIA_LIBRARY را در بخش r2_buckets فایل wrangler.jsonc فعال کنید. دوباره مستقر کنید. بخش عکس‌ها و لینک‌ها تا ۲۰ مورد از هرکدام نگه می‌دارد؛ عمومی کردن باکت یا r2.dev لازم نیست."],["Connect & register the webhook","اتصال و ثبت وب‌هوک","Deploy. In Settings here, enter the Worker HTTPS URL and ADMIN_KEY, then Test connection. Choose Register webhook to securely call setWebhook with secret_token and the /webhook endpoint. Check status with getWebhookInfo in the Telegram API if needed.","پس از استقرار، آدرس HTTPS و ADMIN_KEY را در تنظیمات اینجا وارد کنید و اتصال را بررسی کنید. ثبت وب‌هوک، setWebhook را با secret_token و مسیر /webhook اجرا می‌کند."],["Launch your Mini App","راه‌اندازی مینی‌اپ","In BotFather, use /setmenubutton and set the deployed Worker URL. Open the app from your bot. Telegram initData is validated on the server with HMAC and a one-hour expiration. In an external browser, ADMIN_KEY is required.","با /setmenubutton در BotFather آدرس Worker را تنظیم کنید. initData در سرور با HMAC و مهلت یک ساعت اعتبارسنجی می‌شود. مرورگر بیرونی به ADMIN_KEY نیاز دارد."],["Publish to a channel","انتشار در کانال","Add your bot as a channel administrator with permission to post. Open Channels, register @username or a -100… ID, and enable Send to channel in the composer. Mini App users must also be channel administrators. Channels and drafts are stored locally per authenticated account. Your channel posting, editing and deletion rights are checked separately.","بات را مدیر کانال با مجوز ارسال کنید. در بخش کانال‌ها آدرس یا شناسه -100… را ثبت و ارسال به کانال را روشن کنید. کاربر مینی‌اپ هم باید مدیر کانال باشد. داده‌های محلی برای هر حساب جداست و مجوز ارسال، ویرایش و حذف جداگانه بررسی می‌شود."]];
export const workerSource = "// TeleRich Studio — Telegram Bot API 10.3\n// Deploy with wrangler.jsonc and BOT_STATE. MEDIA_LIBRARY is the optional private R2 gallery.\n// Secrets: BOT_TOKEN, ADMIN_KEY, WEBHOOK_SECRET. Optional: ADMINS_ID=\"123,456\".\n// Never expose BOT_TOKEN or ADMIN_KEY in index.js. ADMIN_KEY is a trusted operator credential.\nimport html, { guides, releases, setup, workerSource, librarySource, contentSecurityPolicy } from './index.js';\nimport { handleLibrary, libraryScope, libraryState, mediaPayload } from './library.js';\n\nconst encoder = new TextEncoder();\nconst escape = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');\nconst admins = env => String(env.ADMINS_ID || '').split(/[\\s,]+/).filter(Boolean);\nconst allowed = (env, id) => !admins(env).length || admins(env).includes(String(id));\nconst result = (data, status = 200, headers = {}) => Response.json(data, { status, headers: { 'Cache-Control': 'no-store', ...headers } });\nconst fail = (message, status = 400) => Object.assign(new Error(message), { status });\nconst delivery = Symbol('delivery');\nconst libraryOwner = Symbol('libraryOwner');\nconst positiveId = value => Number.isSafeInteger(value) && value > 0;\nconst object = value => value !== null && typeof value === 'object' && !Array.isArray(value);\nasync function readJson(request) {\n  if (Number(request.headers.get('content-length') || 0) > 524288) throw fail('Request too large.', 413);\n  const reader = request.body?.getReader();\n  let length = 0, raw = '';\n  const decoder = new TextDecoder();\n  if (reader) while (true) {\n    const { value, done } = await reader.read();\n    if (done) break;\n    length += value.byteLength;\n    if (length > 524288) { await reader.cancel(); throw fail('Request too large.', 413); }\n    raw += decoder.decode(value, { stream: true });\n  }\n  raw += decoder.decode();\n  let data;\n  try { data = JSON.parse(raw || '{}'); } catch { throw fail('Invalid JSON.'); }\n  if (!object(data)) throw fail('JSON body must be an object.');\n  return data;\n}\nasync function stateCall(env, name, path, data) {\n  if (!env.BOT_STATE) throw fail('BOT_STATE is not configured. Deploy using wrangler.jsonc.', 503);\n  return env.BOT_STATE.get(env.BOT_STATE.idFromName(name)).fetch('https://state.internal/' + path, { method: 'POST', body: JSON.stringify(data) });\n}\nasync function consumeRate(env, key, limit) {\n  const response = await stateCall(env, 'rate:' + key, 'rate', { limit });\n  if (!response.ok) throw fail('Rate limiter unavailable.', 503);\n  return response.json();\n}\nasync function equal(a, b) {\n  const hash = async s => new Uint8Array(await crypto.subtle.digest('SHA-256', encoder.encode(s)));\n  const [aa, bb] = await Promise.all([hash(a), hash(b)]);\n  let diff = 0;\n  for (let i = 0; i < aa.length; i++) diff |= aa[i] ^ bb[i];\n  return diff === 0;\n}\nasync function hmac(key, data) {\n  const k = await crypto.subtle.importKey('raw', typeof key === 'string' ? encoder.encode(key) : key, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);\n  return crypto.subtle.sign('HMAC', k, encoder.encode(data));\n}\nasync function telegram(env, method, data = {}) {\n  if (!env.BOT_TOKEN) throw fail('BOT_TOKEN is not configured on the Worker.', 503);\n  const payload = JSON.stringify(data), checkpoint = env[delivery];\n  const digest = checkpoint ? [...new Uint8Array(await crypto.subtle.digest('SHA-256', encoder.encode(payload)))].map(v => v.toString(16).padStart(2, '0')).join('') : '';\n  // Checkpoint successful side effects so a later failure does not repeat them.\n  const step = checkpoint ? checkpoint.next++ : 0;\n  const saved = checkpoint?.calls[step];\n  if (saved?.method === method && saved.digest === digest) return saved.result;\n  const media = data.rich_message ? await mediaPayload(env, env[libraryOwner], data) : null;\n  for (let attempt = 0; attempt < 3; attempt++) {\n    let response, body;\n    try {\n      response = await fetch(`https://api.telegram.org/bot${env.BOT_TOKEN}/${method}`, { method: 'POST', headers: media ? {} : { 'Content-Type': 'application/json' }, body: media || payload, signal: AbortSignal.timeout(6000) });\n      body = await response.json();\n    } catch { throw fail('Telegram is temporarily unavailable. Please retry.', 503); }\n    if (body.ok) {\n      if (checkpoint && !['getMe', 'getChat', 'getChatMember'].includes(method)) {\n        checkpoint.calls[step] = { method, digest, result: true };\n        await checkpoint.save();\n      }\n      return body.result;\n    }\n    const status = body.error_code || response.status;\n    if (status === 429 || status >= 500) {\n      const delay = status === 429 ? Math.max(1, Number(body.parameters?.retry_after) || 1) : attempt + 1;\n      if (attempt < 2 && delay <= 3) { await new Promise(resolve => setTimeout(resolve, delay * 1000)); continue; }\n      throw Object.assign(fail('Telegram is temporarily unavailable. Please retry.', 503), { retryAfter: delay });\n    }\n    throw fail(body.description || 'Telegram request failed.', 400);\n  }\n}\nasync function authenticate(request, env) {\n  const token = request.headers.get('Authorization') || '';\n  if (env.ADMIN_KEY && token.startsWith('Bearer ') && await equal(token.slice(7), env.ADMIN_KEY)) return { operator: true };\n  const raw = request.headers.get('X-Telegram-Init-Data');\n  if (!raw) throw fail('Open this app from your Telegram bot, or connect using ADMIN_KEY.', 401);\n  if (!env.BOT_TOKEN) throw fail('BOT_TOKEN is not configured on the Worker.', 503);\n  const params = new URLSearchParams(raw);\n  const signature = params.get('hash') || '';\n  params.delete('hash');\n  params.sort();\n  const check = [...params.entries()].map(([k, v]) => `${k}=${v}`).join('\\n');\n  const secret = await hmac('WebAppData', env.BOT_TOKEN);\n  const computed = [...new Uint8Array(await hmac(secret, check))].map(v => v.toString(16).padStart(2, '0')).join('');\n  if (!await equal(computed, signature)) throw fail('Invalid Telegram session signature.', 401);\n  const age = Date.now() / 1000 - Number(params.get('auth_date'));\n  if (!Number.isFinite(age) || age < -30 || age > 3600) throw fail('Your Telegram session expired. Reopen the Mini App.', 401);\n  let user;\n  try { user = JSON.parse(params.get('user') || '{}'); } catch { throw fail('Invalid Telegram user.', 401); }\n  if (!object(user) || !positiveId(user.id)) throw fail('No Telegram user in session.', 401);\n  if (!allowed(env, user.id)) throw fail('This bot is restricted to its configured administrators.', 403);\n  return { operator: false, user };\n}\nfunction requireBotPermission(chat, bot, action) {\n  if (chat.type !== 'channel' || bot.status === 'creator') return;\n  const permitted = action === 'delete' ? bot.can_delete_messages || bot.can_post_messages : action === 'edit' ? bot.can_edit_messages || bot.can_post_messages : bot.can_post_messages;\n  if (!permitted) throw fail('The bot lacks permission for this operation.', 403);\n}\nasync function authorizeChat(env, identity, chatId, action = 'send', messageId) {\n  if (!(Number.isSafeInteger(chatId) && chatId !== 0) && !(typeof chatId === 'string' && /^(@[A-Za-z][\\w]{3,}|-?\\d+)$/.test(chatId))) throw fail('A valid chat ID is required.');\n  const chat = await telegram(env, 'getChat', { chat_id: chatId });\n  if (identity.operator) {\n    if (chat.type === 'channel' || chat.type === 'supergroup' || chat.type === 'group') {\n      const me = await telegram(env, 'getMe');\n      const member = await telegram(env, 'getChatMember', { chat_id: chat.id, user_id: me.id });\n      if (!['administrator', 'creator'].includes(member.status)) throw fail('Add the bot as a chat administrator before publishing.', 403);\n      requireBotPermission(chat, member, action);\n    }\n    return chat;\n  }\n  if (chat.type === 'private') {\n    if (String(chat.id) !== String(identity.user.id)) throw fail('You may only send to your own private chat.', 403);\n    return chat;\n  }\n  const me = await telegram(env, 'getMe');\n  const [user, bot] = await Promise.all([\n    telegram(env, 'getChatMember', { chat_id: chat.id, user_id: identity.user.id }),\n    telegram(env, 'getChatMember', { chat_id: chat.id, user_id: me.id })\n  ]);\n  if (!['administrator', 'creator'].includes(user.status)) throw fail('You must be an administrator of the destination.', 403);\n  if (!['administrator', 'creator'].includes(bot.status)) throw fail('The bot must be an administrator of the destination.', 403);\n  requireBotPermission(chat, bot, action);\n  const permission = action === 'delete' ? 'can_delete_messages' : action === 'edit' && chat.type === 'channel' ? 'can_edit_messages' : chat.type === 'channel' ? 'can_post_messages' : null;\n  if (user.status !== 'creator' && permission && !user[permission]) throw fail('You do not have permission for this operation.', 403);\n  if (action === 'edit' && chat.type !== 'channel' && user.status !== 'creator') {\n    const response = await stateCall(env, 'chat:' + chat.id, 'owner', { message_id: messageId });\n    const owner = await response.json();\n    if (!response.ok || owner.user_id !== identity.user.id) throw fail('You may only edit group messages created by you.', 403);\n  }\n  return chat;\n}\nfunction validateRich(rich) {\n  if (!object(rich)) throw fail('rich_message is required.');\n  const keys = ['html', 'markdown', 'blocks'].filter(k => rich[k] !== undefined);\n  if (keys.length !== 1) throw fail('Use exactly one of html, markdown or blocks.');\n  if (keys[0] !== 'blocks' && (typeof rich[keys[0]] !== 'string' || !rich[keys[0]].trim() || rich[keys[0]].length > 32768)) throw fail('Message must contain 1–32,768 characters.');\n  if (keys[0] === 'blocks' && (!Array.isArray(rich.blocks) || !rich.blocks.length || rich.blocks.length > 100 || rich.blocks.some(block => !object(block) || typeof block.type !== 'string'))) throw fail('blocks must contain 1–100 typed objects.');\n  return rich;\n}\nconst copyFields = (source, names) => Object.fromEntries(names.filter(k => source[k] !== undefined).map(k => [k, source[k]]));\nfunction validateKeyboard(markup) {\n  if (!object(markup) || !Array.isArray(markup.inline_keyboard) || markup.inline_keyboard.length > 20) throw fail('Invalid inline keyboard.');\n  let count = 0;\n  const actions = ['url', 'callback_data', 'web_app', 'switch_inline_query', 'switch_inline_query_current_chat', 'switch_inline_query_chosen_chat', 'copy_text', 'disabled'];\n  for (const row of markup.inline_keyboard) {\n    if (!Array.isArray(row) || !row.length || row.length > 8) throw fail('Keyboard rows must contain 1–8 buttons.');\n    for (const button of row) {\n      if (++count > 100 || !object(button) || typeof button.text !== 'string' || !button.text.trim() || button.text.length > 256) throw fail('Invalid keyboard button.');\n      if (button.disabled !== undefined && button.disabled !== true) throw fail('disabled must be true.');\n      for (const key of ['switch_inline_query', 'switch_inline_query_current_chat']) if (button[key] !== undefined && typeof button[key] !== 'string') throw fail('Invalid inline query.');\n      if (button.switch_inline_query_chosen_chat !== undefined && !object(button.switch_inline_query_chosen_chat)) throw fail('Invalid chosen chat action.');\n      const present = actions.filter(key => button[key] !== undefined && !(button.disabled && key === 'callback_data'));\n      if (present.length !== 1) throw fail('Each button must have exactly one action.');\n      if (button.callback_data !== undefined && !button.disabled && (typeof button.callback_data !== 'string' || !encoder.encode(button.callback_data).length || encoder.encode(button.callback_data).length > 64)) throw fail('callback_data must contain 1–64 bytes.');\n      if (button.url !== undefined && (typeof button.url !== 'string' || !/^(https:\\/\\/|tg:\\/\\/)/i.test(button.url))) throw fail('Button URLs require HTTPS or tg://.');\n      if (button.web_app !== undefined && (!object(button.web_app) || typeof button.web_app.url !== 'string' || !/^https:\\/\\//i.test(button.web_app.url))) throw fail('Web App URLs require HTTPS.');\n      if (button.copy_text !== undefined && (!object(button.copy_text) || typeof button.copy_text.text !== 'string' || !button.copy_text.text.length || button.copy_text.text.length > 256)) throw fail('Copy text must contain 1–256 characters.');\n    }\n  }\n}\n\n// One persistent object per update/rate key/chat. A serialized promise chain\n// protects concurrent requests without holding a database transaction over HTTP.\nexport class BotState {\n  constructor(state, env) { this.state = state; this.env = env; this.pending = Promise.resolve(); }\n  fetch(request) {\n    const response = this.pending.catch(() => {}).then(() => this.handle(request));\n    this.pending = response;\n    return response;\n  }\n  async handle(request) {\n    if (new URL(request.url).pathname.startsWith('/library/')) return handleLibrary(request, this.state.storage, this.env);\n    const path = new URL(request.url).pathname, data = await readJson(request), storage = this.state.storage;\n    if (path === '/rate') {\n      const now = Date.now(), previous = await storage.get('rate');\n      const rate = previous && previous.reset > now ? previous : { count: 0, reset: now + 60000 };\n      if (rate.count >= data.limit) return result({ allowed: false, retryAfter: Math.max(1, Math.ceil((rate.reset - now) / 1000)) });\n      rate.count++;\n      await storage.put('rate', rate);\n      await storage.setAlarm(rate.reset);\n      return result({ allowed: true });\n    }\n    if (path === '/owner') {\n      if (!positiveId(data.message_id)) return result({}, 400);\n      const key = 'message:' + data.message_id;\n      if (data.remove) { await storage.delete(key); return result({}); }\n      if (data.user_id !== undefined) {\n        await storage.put(key, { user_id: data.user_id });\n      }\n      const owner = await storage.get(key);\n      return result(owner ? { user_id: owner.user_id } : {});\n    }\n    if (path !== '/update') return result({}, 404);\n    const digest = [...new Uint8Array(await crypto.subtle.digest('SHA-256', encoder.encode(JSON.stringify(data.update))))].map(v => v.toString(16).padStart(2, '0')).join('');\n    const previous = await storage.get('update');\n    if (previous && previous.digest !== digest) return new Response('Update mismatch', { status: 400 });\n    if (previous?.done) return new Response('OK');\n    const record = previous || { digest, calls: [], rateChecked: false };\n    await storage.setAlarm(Date.now() + 86400000);\n    const checkpoint = { calls: record.calls, next: 0, save: () => storage.put('update', record) };\n    const env = { ...this.env, [delivery]: checkpoint };\n    try {\n      if (!record.rateChecked) {\n        const user = data.update.callback_query?.from || data.update.message?.from;\n        if (user) {\n          const rate = await consumeRate(env, 'webhook:' + user.id, 20);\n          if (!rate.allowed) return new Response('Rate limited', { status: 503, headers: { 'Retry-After': String(rate.retryAfter) } });\n        }\n        record.rateChecked = true;\n        await checkpoint.save();\n      }\n      try { await onUpdate(data.update, env, data.origin); }\n      catch (error) {\n        if (!error.status || error.status >= 500) throw error;\n        const chat = data.update.message?.chat || data.update.callback_query?.message?.chat;\n        if (chat?.type === 'private') await plain(env, chat.id, `⚠️ ${escape(error.message)}\\n\\n/help — menu / راهنما`);\n      }\n      record.done = true;\n      // Completed updates only retain a digest and a completion flag.\n      record.calls = [];\n      await storage.put('update', record);\n      return new Response('OK');\n    } catch (error) {\n      return new Response('Temporary processing failure', { status: 503, headers: { 'Retry-After': String(error.retryAfter || 2) } });\n    }\n  }\n  async alarm() {\n    const rate = await this.state.storage.get('rate');\n    if (rate?.reset > Date.now()) { await this.state.storage.setAlarm(rate.reset); return; }\n    await this.state.storage.deleteAll();\n  }}\n\nasync function webApi(request, env, url) {\n  if (request.method !== 'POST') throw fail('POST required.', 405);\n  const identity = await authenticate(request, env);\n  const rate = await consumeRate(env, identity.operator ? 'operator' : 'user:' + identity.user.id, 60);\n  if (!rate.allowed) throw Object.assign(fail('Too many requests. Please wait.', 429), { retryAfter: rate.retryAfter });\n  const action = url.pathname.slice(5);\n  if (action.startsWith('library/')) return libraryState(env, libraryScope(env, identity), action.slice(8), request);\n  const data = await readJson(request);\n  env = { ...env, [libraryOwner]: libraryScope(env, identity) };\n  if (action === 'connect') {\n    const bot = await telegram(env, 'getMe');\n    return { ...bot, workspace_id: bot.id + ':' + (identity.operator ? 'operator' : 'user:' + identity.user.id) };\n  }\n  if (action === 'webhook') {\n    if (!identity.operator) throw fail('Only the operator may change the webhook.', 403);\n    if (!env.WEBHOOK_SECRET) throw fail('Set WEBHOOK_SECRET first.');\n    const webhook = await telegram(env, 'setWebhook', { url: `${url.origin}/webhook`, secret_token: env.WEBHOOK_SECRET, allowed_updates: ['message', 'callback_query', 'my_chat_member', 'stopped_message_generation'] });\n    const commands = await telegram(env, 'setMyCommands', { commands: [\n      { command: 'start', description: 'Open TeleRich · باز کردن تله‌ریچ' },\n      { command: 'guide', description: 'Rich text guide · راهنمای متن ریچ' },\n      { command: 'html', description: 'Blocks & layout guide · راهنمای بلوک‌ها' },\n      { command: 'media', description: 'Media guide · راهنمای مدیا' },\n      { command: 'buttons', description: 'Rich buttons example · نمونه دکمه ریچ' },\n      { command: 'table', description: 'Table example · نمونه جدول' },\n      { command: 'demo', description: 'Full feature demo · دموی کامل' },\n      { command: 'setup', description: 'Deployment guide · راهنمای راه‌اندازی' },\n      { command: 'updates', description: 'Bot API 10.3 changes · تازه‌های نسخه' },\n      { command: 'webapp', description: 'Open the studio · باز کردن استودیو' },\n      { command: 'post', description: 'Channel studio · پست‌ساز کانال' },\n      { command: 'whoami', description: 'Your numeric ID · شناسه عددی شما' },\n      { command: 'about', description: 'Credits · درباره' },\n    ] });\n    return { webhook, commands };\n  }\n  if (!['send', 'edit', 'delete', 'channel', 'draft', 'editEphemeralMessageText', 'editEphemeralMessageCaption', 'editEphemeralMessageReplyMarkup', 'deleteEphemeralMessage'].includes(action)) throw fail('Unknown API route.', 404);\n  if (['edit', 'delete'].includes(action) && !positiveId(data.message_id)) throw fail('A positive message_id is required.');\n  if (data.reply_markup !== undefined) validateKeyboard(data.reply_markup);\n  for (const key of ['disable_notification', 'protect_content', 'can_stop', 'keep_on_stop']) if (data[key] !== undefined && typeof data[key] !== 'boolean') throw fail(key + ' must be boolean.');\n  if (data.message_thread_id !== undefined && !positiveId(data.message_thread_id)) throw fail('Invalid message_thread_id.');\n  const chatId = data.chat_id || identity.user?.id;\n  const operation = action === 'delete' ? 'delete' : action === 'edit' ? 'edit' : action.includes('Ephemeral') ? 'ephemeral' : 'send';\n  const chat = await authorizeChat(env, identity, chatId, operation, data.message_id);\n  if (action === 'channel') return { id: chat.id, title: chat.title, type: chat.type };\n  if (action === 'send') {\n    const fields = copyFields(data, ['disable_notification', 'protect_content', 'ephemeral_message_parameters', 'reply_markup', 'reply_parameters', 'message_thread_id']);\n    if (fields.ephemeral_message_parameters && (!['group', 'supergroup'].includes(chat.type) || !object(fields.ephemeral_message_parameters) || !positiveId(fields.ephemeral_message_parameters.receiver_user_id))) throw fail('Ephemeral messages require a group and a positive receiver_user_id.');\n    const sent = await telegram(env, 'sendRichMessage', { ...fields, chat_id: chat.id, rich_message: validateRich(data.rich_message) });\n    if (['group', 'supergroup'].includes(chat.type) && sent.message_id) {\n      const response = await stateCall(env, 'chat:' + chat.id, 'owner', { message_id: sent.message_id, user_id: identity.operator ? 'operator' : identity.user.id });\n      if (!response.ok) throw fail('Message sent, but ownership could not be saved.', 503);\n    }\n    return sent;\n  }\n  if (action === 'draft') {\n    if (chat.type !== 'private' || !positiveId(data.draft_id)) throw fail('Drafts require a private chat and a positive draft_id.');\n    return telegram(env, 'sendRichMessageDraft', { ...copyFields(data, ['draft_id', 'can_stop', 'keep_on_stop', 'message_thread_id']), chat_id: chat.id, rich_message: validateRich(data.rich_message) });\n  }\n  if (action === 'edit') {\n    if (!Number.isSafeInteger(data.message_id)) throw fail('A valid message_id is required.');\n    return telegram(env, 'editMessageText', { chat_id: chat.id, message_id: data.message_id, rich_message: validateRich(data.rich_message), ...copyFields(data, ['reply_markup']) });\n  }\n  if (action === 'delete') {\n    if (!Number.isSafeInteger(data.message_id)) throw fail('A valid message_id is required.');\n    const deleted = await telegram(env, 'deleteMessage', { chat_id: chat.id, message_id: data.message_id });\n    if (['group', 'supergroup'].includes(chat.type)) await stateCall(env, 'chat:' + chat.id, 'owner', { message_id: data.message_id, remove: true });\n    return deleted;\n  }\n  if (!['group', 'supergroup'].includes(chat.type)) throw fail('Ephemeral messages require a group.');\n  const fields = copyFields(data, ['receiver_user_id', 'ephemeral_message_id', 'rich_message', 'text', 'parse_mode', 'caption', 'caption_entities', 'show_caption_above_media', 'reply_markup']);\n  if (!positiveId(fields.receiver_user_id) || !positiveId(fields.ephemeral_message_id)) throw fail('receiver_user_id and ephemeral_message_id are required.');\n  if (!identity.operator && fields.receiver_user_id !== identity.user.id) throw fail('Cannot modify another user’s ephemeral messages.', 403);\n  if (fields.rich_message) validateRich(fields.rich_message);\n  return telegram(env, action, { ...fields, chat_id: chat.id });\n}\n\nfunction menu(lang, origin) {\n  const fa = lang === 'fa';\n  return { inline_keyboard: [\n    [{ text: fa ? '✨ استودیوی پیام و پست‌ساز' : '✨ Message & channel studio', web_app: { url: origin }, style: 'primary' }],\n    [{ text: fa ? '📖 راهنمای متن ریچ' : '📖 Rich text guide', callback_data: `list:${lang}:Rich text:0` }, { text: fa ? '🧩 بلوک‌ها' : '🧩 Blocks', callback_data: `list:${lang}:Blocks:0` }],\n    [{ text: fa ? '🖼 راهنمای مدیا' : '🖼 Media guide', callback_data: `list:${lang}:Media:0` }, { text: fa ? '🎨 دمو کامل' : '🎨 Full demo', callback_data: `demo:${lang}:0`, style: 'success' }],\n    [{ text: fa ? '🚀 راه‌اندازی' : '🚀 Deployment', callback_data: `setup:${lang}` }, { text: 'Bot API 10.3', callback_data: `updates:${lang}` }],\n    [{ text: fa ? '🌐 English' : '🌐 فارسی', callback_data: `home:${fa ? 'en' : 'fa'}` }]\n  ] };\n}\nconst back = (lang, origin) => ({ inline_keyboard: [[{ text: lang === 'fa' ? '← بازگشت به منو' : '← Back to menu', callback_data: `home:${lang}` }, { text: lang === 'fa' ? 'باز کردن استودیو' : 'Open studio', web_app: { url: origin }, style: 'primary' }]] });\nasync function plain(env, chatId, text, markup, messageId) {\n  return telegram(env, messageId ? 'editMessageText' : 'sendMessage', { chat_id: chatId, ...(messageId ? { message_id: messageId } : {}), text, parse_mode: 'HTML', reply_markup: markup, link_preview_options: { is_disabled: true } });\n}\nasync function home(env, chatId, lang, origin, messageId) {\n  const en = '<b>✨ TeleRich · Rich Message Studio</b>\\n\\nSend HTML or Markdown to render a rich message with Bot API 10.3.\\n\\nExplore individual guides, code examples and live demos. Open the studio for button styles, row layout, media and channel publishing.\\n\\n/start — menu\\n/help — guides\\n/post — channel studio\\n/about — credits';\n  const fa = '<b>✨ TeleRich · استودیوی پیام ریچ</b>\\n\\nمتن HTML یا Markdown بفرستید تا با Bot API 10.3 به پیام ریچ تبدیل شود.\\n\\nراهنمای هر قابلیت، نمونه کد و دموی زنده در دسترس است. برای تنظیم رنگ و ردیف دکمه، مدیا و ارسال به کانال، استودیو را باز کنید.\\n\\n/start — منو\\n/help — راهنما\\n/post — پست‌ساز\\n/about — درباره';\n  const text = en + '\\n\\n〰️〰️〰️〰️〰️〰️〰️〰️\\n\\n' + fa;\n  return plain(env, chatId, text, menu(lang, origin), messageId);\n}\nfunction reconstruct(message) {\n  const text = message.text || message.caption || '';\n  const entities = message.entities || message.caption_entities || [];\n  if (!entities.length) return { [/<\\/?[a-z][\\s\\S]*?>/i.test(text) ? 'html' : 'markdown']: text };\n  const starts = new Map(), ends = new Map();\n  const tags = { bold: ['<b>', '</b>'], italic: ['<i>', '</i>'], underline: ['<u>', '</u>'], strikethrough: ['<s>', '</s>'], spoiler: ['<tg-spoiler>', '</tg-spoiler>'], code: ['<code>', '</code>'], pre: ['<pre><code>', '</code></pre>'], blockquote: ['<blockquote>', '</blockquote>'], expandable_blockquote: ['<blockquote expandable>', '</blockquote>'] };\n  for (const e of [...entities].sort((a, b) => a.offset - b.offset || b.length - a.length)) {\n    let pair = tags[e.type];\n    if (e.type === 'text_link') pair = [`<a href=\"${escape(e.url)}\">`, '</a>'];\n    if (e.type === 'text_mention') pair = [`<a href=\"tg://user?id=${e.user.id}\">`, '</a>'];\n    if (e.type === 'custom_emoji') pair = [`<tg-emoji emoji-id=\"${escape(e.custom_emoji_id)}\">`, '</tg-emoji>'];\n    if (!pair) continue;\n    starts.set(e.offset, (starts.get(e.offset) || '') + pair[0]);\n    ends.set(e.offset + e.length, pair[1] + (ends.get(e.offset + e.length) || ''));\n  }\n  let output = '';\n  for (let i = 0; i <= text.length; i++) output += (ends.get(i) || '') + (starts.get(i) || '') + (i < text.length ? escape(text[i]) : '');\n  return { html: output };\n}\nfunction guideIndexByName(name) { return guides.findIndex(g => g.name === name); }\nasync function sendList(env, chatId, lang, group, offset, origin, messageId) {\n  const list = guides.map((g, i) => ({ ...g, i })).filter(g => g.group === group);\n  offset = Math.max(0, offset || 0);\n  const slice = list.slice(offset, offset + 8);\n  const keyboard = slice.map(g => [{ text: lang === 'fa' ? `${g.fa} · ${g.name}` : g.name, callback_data: `guide:${lang}:${g.i}` }]);\n  const nav = [];\n  if (offset > 0) nav.push({ text: '←', callback_data: `list:${lang}:${group}:${offset - 8}`, style: 'danger' });\n  if (offset + 8 < list.length) nav.push({ text: '→', callback_data: `list:${lang}:${group}:${offset + 8}`, style: 'primary' });\n  if (nav.length) keyboard.push(nav);\n  keyboard.push(back(lang, origin).inline_keyboard[0]);\n  return plain(env, chatId, `<b>${escape(group)} · Bot API 10.3</b>\\n\\n${lang === 'fa' ? 'برای توضیح و نمونه، یک قابلیت انتخاب کنید.' : 'Choose a feature for its explanation and example.'}`, { inline_keyboard: keyboard }, messageId);\n}\nasync function sendGuide(env, chatId, lang, index, origin, messageId) {\n  const guide = guides[index];\n  if (!guide) return;\n  const text = `<b>${escape(guide.name)}</b>\\n\\n${escape(lang === 'fa' ? guide.descriptionFa : guide.description)}\\n\\n<pre>${escape(guide.code)}</pre>\\n\\n<a href=\"https://core.telegram.org/bots/api#${guide.name.toLowerCase()}\">Telegram API reference</a>`;\n  return plain(env, chatId, text, { inline_keyboard: [[{ text: lang === 'fa' ? '▶ نمایش نمونه رندرشده' : '▶ Render this example', callback_data: `render:${lang}:${index}`, style: 'success' }], ...back(lang, origin).inline_keyboard] }, messageId);\n}\nasync function sendDemo(env, chatId, lang, offset, origin, messageId) {\n  offset = Math.max(0, offset || 0);\n  const examples = guides.slice(offset, offset + 5);\n  const nav = [];\n  if (offset > 0) nav.push({ text: lang === 'fa' ? '← بخش قبل' : '← Previous section', callback_data: `demo:${lang}:${Math.max(0, offset - 5)}`, style: 'danger' });\n  if (offset + 5 < guides.length) nav.push({ text: lang === 'fa' ? 'بخش بعد →' : 'Next section →', callback_data: `demo:${lang}:${offset + 5}`, style: 'primary' });\n  const rich_message = { markdown: examples.map(g => `## ${g.name}\\n\\n${g.code}`).join('\\n\\n') };\n  const reply_markup = { inline_keyboard: [...(nav.length ? [nav] : []), ...back(lang, origin).inline_keyboard] };\n  // Bot API 10.2+: editMessageText accepts rich_message, so paging through the demo edits\n  // the same message instead of sending a new one each time next/back is pressed.\n  return telegram(env, messageId ? 'editMessageText' : 'sendRichMessage', { chat_id: chatId, ...(messageId ? { message_id: messageId } : {}), rich_message, reply_markup });\n}\nasync function sendSetup(env, chatId, lang, origin, messageId) {\n  const text = '<b>TeleRich · Deployment / راه‌اندازی</b>\\n\\n' + setup.map((s, i) => `<b>${i + 1}. ${escape(s[lang === 'fa' ? 1 : 0])}</b>\\n${escape(s[lang === 'fa' ? 3 : 2])}`).join('\\n\\n');\n  return plain(env, chatId, text.slice(0, 4000), back(lang, origin), messageId);\n}\nasync function sendUpdates(env, chatId, lang, origin, messageId) {\n  const release = releases[0];\n  const text = `<b>Bot API ${release.version} · ${release.date}</b>\\n\\n` + release.items.map(item => `<b>${escape(item[0])}</b>\\n${escape(item[lang === 'fa' ? 2 : 1])}`).join('\\n\\n') + '\\n\\n<a href=\"https://core.telegram.org/bots/api#august-24-2026\">Official changelog</a>';\n  return plain(env, chatId, text, back(lang, origin), messageId);\n}\nasync function sendWebapp(env, chatId, lang, origin) {\n  return plain(env, chatId, lang === 'fa' ? '✨ استودیوی پیام و پست‌ساز را باز کنید.' : '✨ Open the message & channel studio.', { inline_keyboard: [[{ text: lang === 'fa' ? '✨ باز کردن استودیو' : '✨ Open studio', web_app: { url: origin }, style: 'primary' }], back(lang, origin).inline_keyboard[0]] });\n}\nasync function sendWhoami(env, chatId, lang, origin, user) {\n  const restricted = admins(env).length > 0;\n  const isAdmin = !restricted || admins(env).includes(String(user.id));\n  const text = lang === 'fa'\n    ? `<b>شناسه عددی شما</b>\\n<code>${user.id}</code>\\n\\n${restricted ? (isAdmin ? '✅ شما در فهرست ADMINS_ID هستید.' : '⛔ شما در فهرست ADMINS_ID نیستید و به استودیو دسترسی ندارید.') : 'ℹ️ ADMINS_ID تنظیم نشده؛ استفاده از ربات برای همه آزاد است.'}`\n    : `<b>Your numeric ID</b>\\n<code>${user.id}</code>\\n\\n${restricted ? (isAdmin ? '✅ You are listed in ADMINS_ID.' : '⛔ You are not listed in ADMINS_ID and cannot use the studio.') : 'ℹ️ ADMINS_ID is not set; anyone may use this bot.'}`;\n  return plain(env, chatId, text, back(lang, origin));\n}\n\nasync function onUpdate(update, env, origin) {\n  const callback = update.callback_query;\n  const message = callback?.message || update.message;\n  const user = callback?.from || update.message?.from;\n  if (!user || !message) return;\n  // /whoami is exempt: it is how an owner discovers a user's numeric ID before adding it to ADMINS_ID.\n  if (!callback && message.chat.type === 'private' && (message.text || '').split(' ')[0] === '/whoami') {\n    return sendWhoami(env, message.chat.id, user.language_code?.startsWith('fa') ? 'fa' : 'en', origin, user);\n  }\n  if (!allowed(env, user.id)) {\n    if (callback) await telegram(env, 'answerCallbackQuery', { callback_query_id: callback.id, text: 'Access restricted / دسترسی محدود', show_alert: true });\n    else if (message.chat.type === 'private') await plain(env, message.chat.id, 'Access restricted / دسترسی محدود');\n    return;\n  }\n  // Interactive menus are private-chat only; a bot must not expose another user's draft to a group.\n  if (message.chat.type !== 'private') return;\n  const chatId = message.chat.id;\n  const detectedLang = user.language_code?.startsWith('fa') ? 'fa' : 'en';\n  if (callback) {\n    const [action, rawLang, arg, page] = (callback.data || '').split(':');\n    const lang = rawLang === 'fa' ? 'fa' : 'en';\n    await telegram(env, 'answerCallbackQuery', { callback_query_id: callback.id, text: ['home','list','guide','render','demo','setup','updates','publish','edit','delete'].includes(action) ? undefined : `Callback: ${callback.data || ''}` });\n    if (action === 'home') return home(env, chatId, lang, origin, message.message_id);\n    if (action === 'list') return sendList(env, chatId, lang, ['Rich text','Blocks','Media'].includes(arg) ? arg : 'Rich text', Number(page) || 0, origin, message.message_id);\n    if (action === 'guide') return sendGuide(env, chatId, lang, Number(arg), origin, message.message_id);\n    if (action === 'render') {\n      const guide = guides[Number(arg)];\n      if (guide) return telegram(env, 'sendRichMessage', { chat_id: chatId, rich_message: { markdown: guide.code }, reply_markup: back(lang, origin) });\n    }\n    if (action === 'demo') return sendDemo(env, chatId, lang, Number(arg) || 0, origin, message.message_id);\n    if (action === 'setup') return sendSetup(env, chatId, lang, origin, message.message_id);\n    if (action === 'updates') return sendUpdates(env, chatId, lang, origin, message.message_id);\n    if (action === 'publish' || action === 'edit') {\n      const label = action === 'publish' ? (lang === 'fa' ? 'آدرس @کانال یا شناسه -100… را در پاسخ بفرستید. شما و ربات باید مدیر باشید.' : 'Reply with the destination @channel or -100… ID. You and the bot must be administrators.') : (lang === 'fa' ? 'متن جدید HTML یا Markdown را در پاسخ بفرستید.' : 'Reply with your replacement HTML or Markdown.');\n      return plain(env, chatId, `${label}\\n\\n<code>TR:${action}:${arg}:${lang}</code>`, { force_reply: true, selective: true });\n    }\n    if (action === 'delete') {\n      await telegram(env, 'deleteMessage', { chat_id: chatId, message_id: Number(arg) });\n      return home(env, chatId, lang, origin);\n    }\n    return;\n  }\n  const text = message.text || '';\n  const command = text.split(' ')[0];\n  if (['/start','/help','/post'].includes(command)) return home(env, chatId, detectedLang, origin);\n  if (command === '/about') return plain(env, chatId, '<b>TeleRich · DarknessShade</b>\\n\\n<a href=\"https://github.com/DarknessShade/TeleRich\">GitHub</a>\\n<a href=\"https://t.me/Paradise_Of_Freedom\">Paradise Of Freedom</a>\\n<a href=\"https://t.me/ConfigWireguard\">ConfigWireguard</a>', back(detectedLang, origin));\n  if (command === '/whoami') return sendWhoami(env, chatId, detectedLang, origin, user);\n  if (command === '/guide' || command === '/markdown') return sendList(env, chatId, detectedLang, 'Rich text', 0, origin);\n  if (command === '/html') return sendList(env, chatId, detectedLang, 'Blocks', 0, origin);\n  if (command === '/media') return sendList(env, chatId, detectedLang, 'Media', 0, origin);\n  if (command === '/buttons') { const i = guideIndexByName('RichBlockButtons'); return i >= 0 ? sendGuide(env, chatId, detectedLang, i, origin) : sendList(env, chatId, detectedLang, 'Blocks', 0, origin); }\n  if (command === '/table') { const i = guideIndexByName('RichBlockTable'); return i >= 0 ? sendGuide(env, chatId, detectedLang, i, origin) : sendList(env, chatId, detectedLang, 'Blocks', 0, origin); }\n  if (command === '/demo') return sendDemo(env, chatId, detectedLang, 0, origin);\n  if (command === '/setup') return sendSetup(env, chatId, detectedLang, origin);\n  if (command === '/updates') return sendUpdates(env, chatId, detectedLang, origin);\n  if (command === '/webapp') return sendWebapp(env, chatId, detectedLang, origin);\n  const reply = message.reply_to_message;\n  const marker = reply?.from?.is_bot && reply.text?.match(/TR:(publish|edit):(\\d+):(en|fa)/);\n  if (marker) {\n    const [, action, messageId, lang] = marker;\n    if (action === 'publish') {\n      if (!/^(@[A-Za-z][\\w]{3,}|-100\\d+)$/.test(text.trim())) throw fail('Reply with a valid @channel or -100… identifier.');\n      const target = await authorizeChat(env, { operator: false, user }, text.trim());\n      await telegram(env, 'copyMessage', { chat_id: target.id, from_chat_id: chatId, message_id: Number(messageId) });\n      return plain(env, chatId, lang === 'fa' ? '✅ پست منتشر شد.' : '✅ Your post is published.', back(lang, origin));\n    }\n    return telegram(env, 'editMessageText', { chat_id: chatId, message_id: Number(messageId), rich_message: reconstruct(message) });\n  }\n  if (!text.trim()) return plain(env, chatId, detectedLang === 'fa' ? 'برای مدیا، دکمه و چیدمان پیشرفته، استودیو را باز کنید.' : 'Open the studio to add media, buttons and advanced layouts.', back(detectedLang, origin));\n  return telegram(env, 'sendRichMessage', { chat_id: chatId, rich_message: validateRich(reconstruct(message)) });\n}\n\nexport default {\n  async fetch(request, env) {\n    const url = new URL(request.url);\n    const origin = request.headers.get('Origin');\n    const permitted = !env.ALLOWED_ORIGIN || origin === env.ALLOWED_ORIGIN || origin === url.origin;\n    const cors = { 'Access-Control-Allow-Origin': env.ALLOWED_ORIGIN ? (permitted ? origin || url.origin : url.origin) : '*', 'Access-Control-Allow-Methods': 'POST, OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Telegram-Init-Data, X-File-Name', 'Access-Control-Max-Age': '86400', 'Vary': 'Origin' };\n    if (request.method === 'OPTIONS') return new Response(null, { status: permitted ? 204 : 403, headers: cors });\n    if (url.pathname === '/webhook') {\n      if (request.method !== 'POST') return new Response('POST required', { status: 405 });\n      const received = request.headers.get('X-Telegram-Bot-Api-Secret-Token') || '';\n      if (!env.WEBHOOK_SECRET || !await equal(received, env.WEBHOOK_SECRET)) return new Response('Unauthorized', { status: 401 });\n      try {\n        const update = await readJson(request);\n        if (!Number.isSafeInteger(update.update_id) || update.update_id < 0) throw fail('Invalid update_id.');\n        return await stateCall(env, 'update:' + update.update_id, 'update', { update, origin: url.origin });\n      } catch (error) { return new Response(error.status >= 500 ? 'Processing unavailable' : error.message, { status: error.status || 503 }); }\n    }\n    if (url.pathname.startsWith('/api/')) {\n      if (!permitted) return result({ ok: false, description: 'Origin not allowed.' }, 403, cors);\n      try {\n        const value = await webApi(request, env, url);\n        if (value instanceof Response) return new Response(value.body, { status: value.status, headers: { ...Object.fromEntries(value.headers), ...cors } });\n        return result({ ok: true, result: value }, 200, cors);\n      }\n      catch (error) { return result({ ok: false, description: error.message || 'Request failed.' }, error.status || 500, { ...cors, ...(error.retryAfter ? { 'Retry-After': String(error.retryAfter) } : {}) }); }\n    }\n    if (request.method === 'GET' && url.pathname === '/worker.js') return new Response(workerSource, { headers: { 'Content-Type': 'text/javascript; charset=utf-8', 'Cache-Control': 'no-cache' } });\n    if (request.method === 'GET' && url.pathname === '/library.js') return new Response(librarySource, { headers: { 'Content-Type': 'text/javascript; charset=utf-8', 'Cache-Control': 'no-cache' } });\n    if (request.method === 'GET' && url.pathname === '/index.js') {\n      const values = { guides, releases, setup, workerSource, librarySource, contentSecurityPolicy };\n      const source = Object.entries(values).map(([key, value]) => `export const ${key} = ${JSON.stringify(value)};`).join('\\n') + '\\nexport default ' + JSON.stringify(html) + ';\\n';\n      return new Response(source, { headers: { 'Content-Type': 'text/javascript; charset=utf-8', 'Cache-Control': 'no-cache' } });\n    }\n    if (request.method === 'GET' && url.pathname === '/') return new Response(html, { headers: { 'Content-Type': 'text/html; charset=utf-8', 'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'no-referrer', 'Content-Security-Policy': contentSecurityPolicy, 'Permissions-Policy': 'camera=(), microphone=(), geolocation=()', 'Cache-Control': 'no-cache' } });\n    return new Response('Not found', { status: 404 });\n  }\n};\n";
export const librarySource = "export const IMAGE_LIMIT = 20;\nexport const LINK_LIMIT = 20;\nexport const MAX_IMAGE_BYTES = 5 * 1024 * 1024;\nconst error = (message, status = 400) => Object.assign(new Error(message), { status });\nconst uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;\nconst json = (value, status = 200) => Response.json(value, { status, headers: { 'Cache-Control': 'no-store' } });\n\nexport function libraryScope(env, identity) {\n const bot = String(env.BOT_TOKEN || '').split(':')[0];\n if (!/^\\d+$/.test(bot)) throw error('BOT_TOKEN is not configured on the Worker.', 503);\n const admins = [...new Set(String(env.ADMINS_ID || '').split(/[\\s,]+/).filter(id => /^\\d+$/.test(id)))];\n const owner = identity.operator ? (admins.length === 1 ? 'user:' + admins[0] : 'operator') : 'user:' + identity.user.id;\n return bot + ':' + owner;\n}\n\nexport function libraryState(env, scope, action, body = {}) {\n if (!env.BOT_STATE) throw error('BOT_STATE is not configured.', 503);\n const headers = { 'X-Library-Scope': scope };\n if (body instanceof Request) {\n  headers['Content-Type'] = body.headers.get('Content-Type') || 'application/json';\n  headers['X-File-Name'] = body.headers.get('X-File-Name') || '';\n  body = body.body;\n } else { headers['Content-Type'] = 'application/json'; body = JSON.stringify(body); }\n return env.BOT_STATE.get(env.BOT_STATE.idFromName('library:' + scope)).fetch('https://state.internal/library/' + action, { method: 'POST', headers, body, duplex: 'half' });\n}\n\nasync function bytes(request, maximum) {\n if (Number(request.headers.get('Content-Length') || 0) > maximum) throw error('File or request exceeds the size limit.', 413);\n const reader = request.body?.getReader(), chunks = []; let size = 0;\n if (reader) while (true) {\n  const { value, done } = await reader.read(); if (done) break;\n  size += value.byteLength;\n  if (size > maximum) { await reader.cancel(); throw error('File or request exceeds the size limit.', 413); }\n  chunks.push(value);\n }\n const data = new Uint8Array(size); let offset = 0;\n for (const chunk of chunks) { data.set(chunk, offset); offset += chunk.byteLength; }\n return data;\n}\n\nfunction imageType(data) {\n if (data[0] === 255 && data[1] === 216 && data[2] === 255) return 'image/jpeg';\n if ([137,80,78,71,13,10,26,10].every((value, i) => data[i] === value)) return 'image/png';\n if (new TextDecoder().decode(data.slice(0,4)) === 'RIFF' && new TextDecoder().decode(data.slice(8,12)) === 'WEBP') return 'image/webp';\n return '';\n}\n\nexport async function handleLibrary(request, storage, env) {\n try {\n  const action = new URL(request.url).pathname.slice('/library/'.length);\n  const scope = request.headers.get('X-Library-Scope');\n  if (!/^\\d+:(operator|user:\\d+)$/.test(scope || '')) throw error('Invalid library owner.');\n  const library = await storage.get('library') || { images: [], links: [] };\n  const snapshot = () => ({ images: library.images.map(({ key, ...image }) => image), links: library.links, image_limit: IMAGE_LIMIT, link_limit: LINK_LIMIT, r2_ready: !!env.MEDIA_LIBRARY });\n  if (action === 'list') return json({ ok: true, result: snapshot() });\n  if (action === 'upload') {\n   if (!env.MEDIA_LIBRARY) throw error('Connect the MEDIA_LIBRARY R2 bucket to enable photo uploads.', 503);\n   if (library.images.length >= IMAGE_LIMIT) throw error('Photo library is full (20 photos). Delete a photo first.', 409);\n   const content = await bytes(request, MAX_IMAGE_BYTES), mime = imageType(content);\n   if (!mime || mime !== request.headers.get('Content-Type')) throw error('Choose a JPG, PNG or WebP image.');\n   let name; try { name = decodeURIComponent(request.headers.get('X-File-Name') || 'photo'); } catch { throw error('Invalid file name.'); }\n   if (!name.trim() || name.length > 120) throw error('Photo name must contain 1–120 characters.');\n   const id = crypto.randomUUID(), key = scope + '/' + id;\n   await env.MEDIA_LIBRARY.put(key, content, { httpMetadata: { contentType: mime } });\n   library.images.push({ id, key, name: name.trim(), mime, size: content.byteLength });\n   try { await storage.put('library', library); }\n   catch (cause) { await env.MEDIA_LIBRARY.delete(key); throw cause; }\n   return json({ ok: true, result: snapshot() });\n  }\n  const raw = new TextDecoder().decode(await bytes(request, 16384)); let data;\n  try { data = JSON.parse(raw || '{}'); } catch { throw error('Invalid JSON.'); }\n  if (!data || typeof data !== 'object' || Array.isArray(data)) throw error('JSON body must be an object.');\n  if (action === 'add-link') {\n   if (library.links.length >= LINK_LIMIT) throw error('Link library is full (20 links). Delete a link first.', 409);\n   if (typeof data.name !== 'string' || !data.name.trim() || data.name.length > 80) throw error('Link name must contain 1–80 characters.');\n   let url; try { url = new URL(data.url); } catch { throw error('Enter a valid HTTPS link.'); }\n   if (typeof data.url !== 'string' || data.url.length > 2048 || url.protocol !== 'https:' || url.username || url.password) throw error('Enter a valid HTTPS link.');\n   if (library.links.some(link => link.url === url.href)) throw error('This link is already saved.', 409);\n   library.links.push({ id: crypto.randomUUID(), name: data.name.trim(), url: url.href });\n  } else if (action === 'photo' || action === 'delete-photo') {\n   if (!uuid.test(data.id || '')) throw error('Invalid photo ID.');\n   const image = library.images.find(image => image.id === data.id);\n   if (!image) throw error('Photo is missing or belongs to another library.', 404);\n   if (!env.MEDIA_LIBRARY) throw error('The MEDIA_LIBRARY R2 bucket is not connected.', 503);\n   if (action === 'photo') {\n    const object = await env.MEDIA_LIBRARY.get(image.key);\n    if (!object) throw error('Photo is missing from storage.', 404);\n    return new Response(object.body, { headers: { 'Content-Type': image.mime, 'Content-Length': String(image.size), 'X-Content-Type-Options': 'nosniff', 'Cache-Control': 'no-store' } });\n   }\n   await env.MEDIA_LIBRARY.delete(image.key);\n   library.images = library.images.filter(image => image.id !== data.id);\n  } else if (action === 'delete-link') {\n   if (!library.links.some(link => link.id === data.id)) throw error('Link was not found.', 404);\n   library.links = library.links.filter(link => link.id !== data.id);\n  } else throw error('Unknown library action.', 404);\n  await storage.put('library', library);\n  return json({ ok: true, result: snapshot() });\n } catch (cause) { return json({ ok: false, description: cause.message || 'Library unavailable.' }, cause.status || 503); }\n}\n\nexport async function mediaPayload(env, scope, data) {\n const rich = data.rich_message;\n const ids = [...new Set([...JSON.stringify(rich || {}).matchAll(/tg:\\/\\/photo\\?id=(library_[0-9a-f-]{36})/g)].map(match => match[1]))];\n if (!ids.length) return null;\n if (!scope) throw error('Open the studio to send photos from your library.');\n if (ids.length > IMAGE_LIMIT) throw error('Use at most 20 library photos in a message.');\n if (rich.media !== undefined && !Array.isArray(rich.media)) throw error('Invalid rich message media.');\n const media = [...(rich.media || [])], form = new FormData(); let total = 0;\n for (const [index, id] of ids.entries()) {\n  if (media.some(item => item.id === id)) throw error('Duplicate rich message media ID.');\n  const response = await libraryState(env, scope, 'photo', { id: id.slice(8) });\n  if (!response.ok) { const failure = await response.json(); throw error(failure.description, response.status); }\n  total += Number(response.headers.get('Content-Length'));\n  if (total > 20 * 1024 * 1024) throw error('Selected photos exceed 20 MB for one message.', 413);\n  form.append('photo' + index, await response.blob(), 'photo' + index);\n  media.push({ id, media: { type: 'photo', media: 'attach://photo' + index } });\n }\n for (const [name, value] of Object.entries({ ...data, rich_message: { ...rich, media } })) {\n  if (value !== undefined) form.append(name, typeof value === 'object' ? JSON.stringify(value) : String(value));\n }\n return form;\n}\n";
export const contentSecurityPolicy = "default-src 'none'; script-src 'self' https://telegram.org 'sha256-3hKFqRryUucsVmb1ultTKWVCWjfoEIC56mQGTRe8iys='; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob: https:; media-src https:; font-src 'self' data:; connect-src 'self' https:; frame-src https://www.openstreetmap.org; frame-ancestors 'self' https://web.telegram.org https://*.telegram.org; base-uri 'none'; object-src 'none'; form-action 'none'";
